async function main() {
  const argv = yargs(process.argv.slice(2))
    .option('packages', {
      description: 'which packages to publish, defaults to all',
      choices: PUBLISHABLE_PACKAGES,
      default: PUBLISHABLE_PACKAGES,
    })
    .option('for-real', {
      alias: 'frfr',
      description:
        'whether to publish to npm (npm publish) or dryrun (npm publish --dry-run)',
      type: 'boolean',
      default: false,
    })
    .option('debug', {
      description:
        'If enabled, will always run npm commands in dry run mode irregardless of the for-real flag',
      type: 'boolean',
      default: false,
    })
    .option('ci', {
      description: 'Publish packages via CI',
      type: 'boolean',
      default: false,
    })
    .option('tag', {
      description: 'Tag to publish to npm',
      type: 'choices',
      choices: ['experimental', 'beta', 'rc', 'latest'],
      default: 'experimental',
    })
    .option('tag-version', {
      description:
        'Optional tag version to append to tag name, eg `1` becomes 0.0.0-rc.1',
      type: 'number',
      default: null,
    })
    .option('version-name', {
      description: 'Version name',
      type: 'string',
      default: '0.0.0',
    })
    .help('help')
    .strict()
    .parseSync();

  if (argv.debug === false) {
    const currBranchName = await execHelper('git rev-parse --abbrev-ref HEAD');
    const isPristine = (await execHelper('git status --porcelain')) === '';
    if (currBranchName !== 'main' || isPristine === false) {
      throw new Error(
        'This script must be run from the `main` branch with no uncommitted changes'
      );
    }
  }

  let pkgNames = argv.packages;
  if (Array.isArray(argv.packages) === false) {
    pkgNames = [argv.packages];
  }
  const spinner = ora(
    `Preparing to publish ${argv.versionName}@${argv.tag} ${
      argv.forReal === true ? '(for real)' : '(dry run)'
    } [debug=${argv.debug}]`
  ).info();

  await buildPackages(pkgNames);

  if (argv.forReal === false) {
    spinner.info('Dry run: Report tarball contents');
    for (const pkgName of pkgNames) {
      console.log(`\n========== ${pkgName} ==========\n`);
      spinner.start(`Running npm pack --dry-run\n`);
      try {
        await spawnHelper('npm', ['pack', '--dry-run'], {
          cwd: path.resolve(__dirname, `../../packages/${pkgName}`),
          stdio: 'inherit',
        });
      } catch (e) {
        spinner.fail(e.toString());
        throw e;
      }
      spinner.stop(`Successfully packed ${pkgName} (dry run)`);
    }
    spinner.succeed(
      'Please confirm contents of packages before publishing. You can run this command again with --for-real to publish to npm'
    );
  }

  if (argv.forReal === true) {
    const commit = await execHelper(
      'git show -s --no-show-signature --format=%h',
      {
        cwd: path.resolve(__dirname, '..'),
      }
    );
    const dateString = await getDateStringForCommit(commit);
    const otp =
      argv.ci === false && argv.debug === false ? await promptForOTP() : null;
    const {hash} = await hashElement(path.resolve(__dirname, '../..'), {
      encoding: 'hex',
      folders: {exclude: ['node_modules']},
      files: {exclude: ['.DS_Store']},
    });
    const truncatedHash = hash.slice(0, 7);
    let newVersion;
    if (argv.tag === 'latest') {
      newVersion = argv.versionName;
    } else {
      newVersion =
        argv.tagVersion == null || argv.tagVersion === ''
          ? `${argv.versionName}-${argv.tag}`
          : `${argv.versionName}-${argv.tag}.${argv.tagVersion}`;
    }
    if (argv.tag === 'experimental' || argv.tag === 'beta') {
      newVersion = `${newVersion}-${truncatedHash}-${dateString}`;
    }

    for (const pkgName of pkgNames) {
      const pkgDir = path.resolve(__dirname, `../../packages/${pkgName}`);
      const pkgJsonPath = path.resolve(
        __dirname,
        `../../packages/${pkgName}/package.json`
      );

      spinner.start(`Writing package.json for ${pkgName}@${newVersion}`);
      await writeJson(
        pkgJsonPath,
        {
          ...(await readJson(pkgJsonPath)),
          version: newVersion,
        },
        {spaces: 2}
      );
      spinner.succeed(`Wrote package.json for ${pkgName}@${newVersion}`);

      console.log(`\n========== ${pkgName} ==========\n`);
      spinner.start(`Publishing ${pkgName}@${newVersion} to npm\n`);

      let opts = [];
      if (argv.debug === true) {
        opts.push('--dry-run');
      }
      if (otp != null) {
        opts.push(`--otp=${otp}`);
      }

      opts.push(`--tag=${argv.tag}`);

      try {
        await spawnHelper(
          'npm',
          ['publish', ...opts, '--registry=https://registry.npmjs.org'],
          {
            cwd: pkgDir,
            stdio: 'inherit',
          }
        );
        console.log('\n');
      } catch (e) {
        spinner.fail(e.toString());
        throw e;
      }
      spinner.succeed(`Successfully published ${pkgName} to npm`);

      spinner.start('Pushing tags to npm');
      if (typeof argv.tag === 'string') {
        try {
          let opts = ['dist-tag', 'add', `${pkgName}@${newVersion}`, argv.tag];
          if (otp != null) {
            opts.push(`--otp=${otp}`);
          }
          if (argv.debug === true) {
            spinner.info(`dry-run: npm ${opts.join(' ')}`);
          } else {
            await spawnHelper('npm', opts, {
              cwd: pkgDir,
              stdio: 'inherit',
            });
          }
        } catch (e) {
          spinner.fail(e.toString());
          throw e;
        }
        spinner.succeed(
          `Successfully pushed dist-tag ${argv.tag} for ${pkgName} to npm`
        );
      }
    }

    console.log('\n\n✅ All done');
  }
}

async function buildPackages(pkgNames) {
  const spinner = ora(`Building packages`).info();
  for (const pkgName of pkgNames) {
    const command = `NODE_ENV=production yarn workspace ${pkgName} run build --dts`;
    spinner.start(`Running: ${command}\n`);
    try {
      await execHelper(command);
    } catch (e) {
      spinner.fail(e.toString());
      throw e;
    }
    spinner.succeed(`Successfully built ${pkgName}`);
  }
  spinner.stop();
}

function execHelper(command, options, streamStdout = false) {
  return new Promise((resolve, reject) => {
    const proc = cp.exec(command, options, (error, stdout) =>
      error ? reject(error) : resolve(stdout.trim())
    );
    if (streamStdout) {
      proc.stdout.pipe(process.stdout);
    }
  });
}

function _spawn(command, args, options, cb) {
  const child = cp.spawn(command, args, options);
  child.on('close', exitCode => {
    cb(null, exitCode);
  });
  return child;
}

async function getDateStringForCommit(commit) {
  let dateString = await execHelper(
    `git show -s --no-show-signature --format=%cd --date=format:%Y%m%d ${commit}`
  );

  // On CI environment, this string is wrapped with quotes '...'s
  if (dateString.startsWith("'")) {
    dateString = dateString.slice(1, 9);
  }

  return dateString;
}

fetchPullRequest = async pullNumber => {
  const response = await octokit.request(
    'GET /repos/{owner}/{repo}/pulls/{pull_number}',
    {
      owner: OWNER,
      repo: REPO,
      pull_number: pullNumber,
      headers: {
        'X-GitHub-Api-Version': '2022-11-28',
      },
    }
  );
  return {body: response.data.body, title: response.data.title};
}

function formatCommitMessage(str) {
  let formattedStr = '';
  let line = '';

  const trim = str.replace(/(\r\n|\n|\r)/gm, ' ').trim();
  if (!trim) {
    return '';
  }

  // Split the string into words
  const words = trim.split(' ');
  // Iterate over each word
  for (let i = 0; i < words.length; i++) {
    // If adding the next word doesn't exceed the line length limit, add it to the line
    if ((line + words[i]).length <= 80) {
      line += words[i] + ' ';
    } else {
      // Otherwise, add the line to the formatted string and start a new line
      formattedStr += line + '\n';
      line = words[i] + ' ';
    }
  }
  // Add the last line to the formatted string
  formattedStr += line;
  return formattedStr;
}

function filterMsg(response) {
  const {body, title} = response;

  const msgs = body.split('\n\n').flatMap(x => x.split('\r\n'));

  const newMessage = [];

  // Add title
  msgs.unshift(title);

  for (const msg of msgs) {
    // remove "Stack from [ghstack] blurb"
    if (msg.startsWith('Stack from ')) {
      continue;
    }

    // remove "* #1234"
    if (msg.startsWith('* #')) {
      continue;
    }

    // remove "* __->__ #1234"
    if (msg.startsWith('* __')) {
      continue;
    }

    const formattedStr = formatCommitMessage(msg);
    if (!formattedStr) {
      continue;
    }
    newMessage.push(formattedStr);
  }

  const updatedMsg = newMessage.join('\n\n');
  return updatedMsg;
}

function parsePullRequestNumber(text) {
  if (!text) {
    return null;
  }
  const ghstackUrlRegex =
    /https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/pull\/(\d+)/;
  const ghstackMatch = text.match(ghstackUrlRegex);
  if (ghstackMatch) {
    return ghstackMatch[1];
  }
  const firstLine = text.split('\n').filter(text => text.trim().length > 0)[0];
  if (firstLine == null) {
    return null;
  }
  const prNumberRegex = /\(#(\d{3,})\)\s*$/;
  const prNumberMatch = firstLine.match(prNumberRegex);
  if (prNumberMatch) {
    return prNumberMatch[1];
  }
  return null;
}

